+  const style = /\n*<style[^>]*>\n?([\s\S]*?)\n?<\/style>\n*/i.exec(template);
+  const script = /\n*<script[^>]*>\n?([\s\S]*?)\n?<\/script>\n*/i.exec(template);
+  if (!style && !script) continue;
+
+  if (style) {
+    const path = join(directory, "style.css");
+    if (existsSync(path)) throw new Error(`${entry.name}: style.css already exists.`);
+    writeFileSync(path, `${style[1].trim()}\n`);
+  }
+  if (script) {
+    const path = join(directory, "script.js");
+    if (existsSync(path)) throw new Error(`${entry.name}: script.js already exists.`);
+    writeFileSync(path, `${script[1].trim()}\n`);
+  }
